# WSL shell setup. It works on a distro that already exists: nothing is
# reinstalled, the Linux part runs as root through wsl.exe (no sudo password),
# and the default shell is changed with chsh as root.

function Get-WinToolWslDistroName {
    param($Step)
    $name = [string](Get-WinToolNote -Object $Step -Name "Distro" -Default "Ubuntu")
    if ([string]::IsNullOrWhiteSpace($name)) {
        $name = "Ubuntu"
    }
    if ($name -notmatch '^[A-Za-z0-9._-]+$') {
        throw (Get-WinToolText "msg.unexpected-wsl-distro-name-n" $name)
    }
    return $name
}

function ConvertTo-WinToolShellWord {
    param(
        [AllowEmptyString()][string]$Text
    )
    # Values that reach bash: letters, digits, and . _ / - only.
    return ([string]$Text -replace '[^A-Za-z0-9._/-]', '')
}

function Get-WinToolWslSetupText {
    param(
        [Parameter(Mandatory = $true)]$Step
    )
    $bash = Get-WinToolPayloadText -Name "Wsl"
    $bash = $bash -replace "`r`n", "`n" -replace "`r", "`n"
    $variant = ConvertTo-WinToolShellWord -Text ([string](Get-WinToolNote -Object $Step -Name "Variant" -Default ""))
    $style = ConvertTo-WinToolShellWord -Text ([string](Get-WinToolNote -Object $Step -Name "PromptStyle" -Default ""))
    $omzTheme = ConvertTo-WinToolShellWord -Text ([string](Get-WinToolNote -Object $Step -Name "OmzTheme" -Default ""))
    if ([string]::IsNullOrWhiteSpace($omzTheme)) { $omzTheme = "robbyrussell" }
    $styleFile = ""
    $styleSettings = ""
    $chosen = Get-WinToolPromptVariant -PromptId $variant -PromptStyle $style
    if ($null -ne $chosen) {
        # The style id that reaches bash is always one from the catalog.
        $style = ConvertTo-WinToolShellWord -Text ([string]$chosen.id)
        $styleFile = ConvertTo-WinToolShellWord -Text ([string](Get-WinToolNote -Object $chosen -Name "configFile" -Default ""))
        if ($styleFile.Contains("..")) { $styleFile = "" }
        $styleSettings = (@(Get-WinToolPromptVariantSetting -Variant $chosen) -join "`n")
    }
    $hush = "1"
    $hushFlag = Get-WinToolNote -Object $Step -Name "HideStartupBanner"
    if ($null -ne $hushFlag -and -not [bool]$hushFlag) {
        $hush = "0"
    }
    $header = "export WINTOOL_SHELL_PROMPT='" + $variant + "'`nexport WINTOOL_PROMPT_STYLE='" + $style + "'`nexport WINTOOL_OMZ_THEME='" + $omzTheme + "'`nexport WINTOOL_STYLE_FILE='" + $styleFile + "'`nexport WINTOOL_STYLE_SETTINGS='" + $styleSettings + "'`nexport WINTOOL_HUSHLOGIN='" + $hush + "'`n"
    if ($bash.StartsWith("#!")) {
        $cut = $bash.IndexOf("`n")
        return $bash.Substring(0, $cut + 1) + $header + $bash.Substring($cut + 1)
    }
    return $header + $bash
}

function Get-WinToolWslLookupText {
    return @'
$ErrorActionPreference = "Continue"
$env:WSL_UTF8 = "1"
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { $null = $_ }
function Get-WinToolWslEntry {
    param([string]$Name)
    foreach ($key in @(Get-ChildItem -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Lxss" -ErrorAction SilentlyContinue)) {
        $item = Get-ItemProperty -LiteralPath $key.PSPath -ErrorAction SilentlyContinue
        if ($null -ne $item -and [string]$item.DistributionName -eq $Name) {
            return $item
        }
    }
    return $null
}
function Write-WinToolWslOutput {
    process {
        $text = ([string]$_).Replace([string][char]0, "")
        if (-not [string]::IsNullOrWhiteSpace($text)) { Write-Output $text.TrimEnd() }
    }
}
$wsl = Join-Path $env:SystemRoot "System32\wsl.exe"
'@
}

function Get-WinToolWslInstallScript {
    param(
        [Parameter(Mandatory = $true)][string]$Distro
    )
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add((Get-WinToolWslLookupText))
    $lines.Add('$distro = ' + (ConvertTo-WinToolSingleQuoted -Text $Distro))
    $lines.Add(@'
if ($null -ne (Get-WinToolWslEntry -Name $distro)) {
    Write-Output ("WSL already has " + $distro + ", so it is kept as it is.")
    exit 0
}
if (-not (Test-Path -LiteralPath $wsl)) {
    Write-Output "wsl.exe was not found. WSL needs Windows 10 2004 or later."
    exit 1
}
& $wsl --install -d $distro --no-launch 2>&1 | Write-WinToolWslOutput
$code = $LASTEXITCODE
if ($code -eq 0) {
    Write-Output ("Open " + $distro + " once from the Start menu to create your Linux user, then run the shell setup again.")
}
exit $code
'@)
    return ($lines -join [Environment]::NewLine)
}

function Get-WinToolWslShellScript {
    param(
        [Parameter(Mandatory = $true)][string]$Distro,
        [Parameter(Mandatory = $true)][string]$ScriptPath
    )
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add((Get-WinToolWslLookupText))
    $lines.Add('$distro = ' + (ConvertTo-WinToolSingleQuoted -Text $Distro))
    $lines.Add('$script = ' + (ConvertTo-WinToolSingleQuoted -Text $ScriptPath))
    $lines.Add(@'
$entry = Get-WinToolWslEntry -Name $distro
if ($null -eq $entry) {
    Write-Output ("WSL has no distro named " + $distro + ". If it was just installed, open it once from the Start menu to create your Linux user, then run the shell setup again.")
    exit 3
}
if (-not (Test-Path -LiteralPath $wsl)) {
    Write-Output "wsl.exe was not found."
    exit 1
}
$uid = 0
if ($null -ne $entry.PSObject.Properties["DefaultUid"]) { $uid = [int64]$entry.DefaultUid }
$unix = ""
$converted = & $wsl -d $distro -u root -- wslpath -a $script 2>$null
foreach ($line in @($converted)) {
    $text = ([string]$line).Replace([string][char]0, "").Trim()
    if ($text.StartsWith("/")) { $unix = $text }
}
if ([string]::IsNullOrWhiteSpace($unix)) {
    $unix = "/mnt/" + $script.Substring(0, 1).ToLowerInvariant() + $script.Substring(2).Replace("\", "/")
}
Write-Output ("Running the shell setup in " + $distro + " as root for uid " + $uid + ".")
& $wsl -d $distro -u root -- env ("WINTOOL_UID=" + $uid) bash $unix 2>&1 | Write-WinToolWslOutput
exit $LASTEXITCODE
'@)
    return ($lines -join [Environment]::NewLine)
}

function Set-WinToolWslProfileFont {
    param(
        [Parameter(Mandatory = $true)]$Settings,
        [Parameter(Mandatory = $true)][string]$Distro,
        [Parameter(Mandatory = $true)][string]$Face
    )
    # Sets the font on the distro's own Terminal profile, so an older
    # per-profile font cannot hide the Nerd Font. Returns how many changed.
    $profiles = Get-WinToolNote -Object $Settings -Name "profiles"
    $list = @(Get-WinToolNote -Object $profiles -Name "list" -Default @())
    $count = 0
    foreach ($item in $list) {
        $name = [string](Get-WinToolNote -Object $item -Name "name" -Default "")
        $source = [string](Get-WinToolNote -Object $item -Name "source" -Default "")
        $isWsl = $source -match '(?i)wsl'
        if (-not ($name -eq $Distro -or ($isWsl -and $name.StartsWith($Distro, [System.StringComparison]::OrdinalIgnoreCase)))) {
            continue
        }
        $font = Get-WinToolNote -Object $item -Name "font"
        if ($null -eq $font) {
            $item | Add-Member -NotePropertyName "font" -NotePropertyValue ([pscustomobject]@{ face = $Face }) -Force
        }
        elseif ($null -eq $font.PSObject.Properties["face"]) {
            $font | Add-Member -NotePropertyName "face" -NotePropertyValue $Face
        }
        else {
            $font.face = $Face
        }
        if ($null -ne $item.PSObject.Properties["fontFace"]) {
            $item.PSObject.Properties.Remove("fontFace")
        }
        $count++
    }
    return $count
}

function Invoke-WinToolWslTerminalProfile {
    param(
        [Parameter(Mandatory = $true)][string]$Distro,
        [string]$Face,
        [string]$Match
    )
    if ([string]::IsNullOrWhiteSpace($Face)) {
        return
    }
    $chosen = Resolve-WinToolInstalledFontFace -Face $Face -Match $Match
    if ($null -eq $chosen) {
        return
    }
    $path = Get-WinToolTerminalSettingsPath
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) {
        Write-WinToolLog -Message (Get-WinToolText "msg.windows-terminal-settings-were-not-found-so-the-n-profil" $Distro) -Level "warn"
        return
    }
    Backup-WinToolTerminalSetting -Path $path
    $raw = [System.IO.File]::ReadAllText($path)
    if ([string]::IsNullOrWhiteSpace($raw)) {
        Write-WinToolLog -Message (Get-WinToolText "msg.windows-terminal-settings-are-empty-so-the-n-profile-fon" $Distro) -Level "warn"
        return
    }
    $settings = ConvertFrom-WinToolJsonText -Text $raw
    $count = Set-WinToolWslProfileFont -Settings $settings -Distro $Distro -Face $chosen
    if ($count -eq 0) {
        Write-WinToolLog -Message (Get-WinToolText "msg.windows-terminal-has-no-n-profile-yet-it-will-use-the-de" $Distro $chosen) -Level "info"
        return
    }
    Write-WinToolUtf8File -Path $path -Text ((ConvertTo-WinToolJsonText -Value $settings) + "`n")
    Write-WinToolLog -Message (Get-WinToolText "msg.set-the-n-profile-font-in-windows-terminal-to-n" $Distro $chosen) -Level "ok"
}

function Get-WinToolWslStep {
    param(
        [string]$Distro = "Ubuntu",
        [string]$PromptId = "oh-my-zsh",
        [string]$PromptStyle = "",
        $Font,
        [bool]$Install = $true,
        [bool]$Shell = $true
    )
    $steps = New-Object System.Collections.Generic.List[object]
    if ($Install) {
        [void]$steps.Add([pscustomobject]@{ Type = "wsl-install"; Label = (Get-WinToolText "msg.install-wsl-with-n-kept-if-it-already-exists" $Distro); Distro = $Distro })
    }
    if ($Shell) {
        $label = "Install zsh and Oh My Zsh in $Distro"
        if ($PromptId -eq "tide") { $label = "Install Fish and Tide in $Distro" }
        elseif ($PromptId -eq "powerlevel10k") { $label = "Install Powerlevel10k in $Distro" }
        elseif ($PromptId -eq "pure") { $label = "Install Pure in $Distro" }
        elseif ($PromptId -eq "spaceship") { $label = "Install Spaceship in $Distro" }
        elseif ($PromptId -eq "oh-my-zsh") { $label = "Install the Oh My Zsh theme in $Distro" }
        elseif ($PromptId -eq "oh-my-posh") { $label = "Install zsh and Oh My Posh in $Distro" }
        elseif ($PromptId -eq "starship") { $label = "Install zsh and Starship in $Distro" }
        $chosen = Get-WinToolPromptVariant -PromptId $PromptId -PromptStyle $PromptStyle
        if ($null -ne $chosen) {
            $label += " (" + [string]$chosen.name + " style)"
            $PromptStyle = [string]$chosen.id
        }
        [void]$steps.Add([pscustomobject]@{ Type = "wsl-shell"; Label = $label; Distro = $Distro; Variant = $PromptId; PromptStyle = $PromptStyle; OmzTheme = $PromptStyle })
    }
    if ($null -ne $Font) {
        [void]$steps.Add([pscustomobject]@{ Type = "wsl-profile"; Label = ("Use " + [string]$Font.name + " in the $Distro Terminal profile"); Distro = $Distro; Face = [string]$Font.face; Match = [string]$Font.match })
    }
    return $steps.ToArray()
}

function Get-WinToolWslShellPlan {
    param(
        [string]$Distro = "Ubuntu",
        [string]$PromptId = "oh-my-posh",
        [string]$PromptStyle = "jandedobbeleer",
        [string]$FontId = "cascadiacode-nf",
        [switch]$Install
    )
    # Only the WSL part of terminal setup: no Windows packages, profiles, or
    # color schemes. Without -Install an existing distro is required.
    $font = $null
    if (-not [string]::IsNullOrWhiteSpace($FontId)) {
        foreach ($item in @(Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "fonts" -Default @())) {
            if ([string]$item.id -eq $FontId) {
                $font = $item
                break
            }
        }
        if ($null -eq $font) {
            throw (Get-WinToolText "msg.unknown-terminal-font-n" $FontId)
        }
    }
    return @(Get-WinToolWslStep -Distro $Distro -PromptId $PromptId -PromptStyle $PromptStyle -Font $font -Install ([bool]$Install) -Shell $true)
}

function Invoke-WinToolWslShellSetup {
    param(
        [string]$Distro = "Ubuntu",
        [string]$PromptId = "oh-my-posh",
        [string]$PromptStyle = "jandedobbeleer",
        [string]$FontId = "cascadiacode-nf",
        [switch]$Install
    )
    $plan = @(Get-WinToolWslShellPlan -Distro $Distro -PromptId $PromptId -PromptStyle $PromptStyle -FontId $FontId -Install:$Install)
    Invoke-WinToolPlan -Step $plan
}
# endregion

# region src/Private/Updates.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Resolve-WinToolGpuVendor {
    param(
        [string]$Name,
        $Vendor
    )
    if ([string]::IsNullOrWhiteSpace($Name)) {
        return $null
    }
    foreach ($item in @($Vendor)) {
        foreach ($token in @(Get-WinToolNote -Object $item -Name "match" -Default @())) {
            if ($Name.IndexOf([string]$token, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                return $item
            }
        }
    }
    return $null
}

function Get-WinToolGpuInfo {
    if (-not (Test-WinToolWindows)) {
        return @()
    }
    $rows = New-Object System.Collections.Generic.List[object]
    try {
        $items = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop)
    }
    catch {
        return @()
    }
    foreach ($item in $items) {
        if ([string]::IsNullOrWhiteSpace([string]$item.Name)) {
            continue
        }
        $rows.Add([pscustomobject]@{
            Name = [string]$item.Name
            DriverVersion = [string]$item.DriverVersion
        })
    }
    return $rows.ToArray()
}

function Get-WinToolUpdateSearchScript {
    $scriptText = @'
param($Sync, $Criteria)
$ErrorActionPreference = "Stop"
try {
    $session = New-Object -ComObject Microsoft.Update.Session
    $searcher = $session.CreateUpdateSearcher()
    $result = $searcher.Search($Criteria)
    $lines = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -lt $result.Updates.Count; $i++) {
        $update = $result.Updates.Item($i)
        $isDriver = $false
        foreach ($category in @($update.Categories)) {
            if ([string]$category.Name -match "Driver") {
                $isDriver = $true
            }
        }
        $kind = "update"
        if ($isDriver) { $kind = "driver" }
        $title = ([string]$update.Title) -replace "[\r\n\t]", " "
        $lines.Add($kind + "`t" + $title)
    }
    $Sync.Lines = $lines.ToArray()
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolUpdateInstallScript {
    $scriptText = @'
param($Sync, $Criteria, $TitleText)
$ErrorActionPreference = "Stop"
try {
    $wanted = @{}
    foreach ($title in @(([string]$TitleText) -split "`n")) {
        if (-not [string]::IsNullOrWhiteSpace([string]$title)) {
            $wanted[[string]$title] = $true
        }
    }
    $session = New-Object -ComObject Microsoft.Update.Session
    $searcher = $session.CreateUpdateSearcher()
    $result = $searcher.Search($Criteria)
    $toInstall = New-Object -ComObject Microsoft.Update.UpdateColl
    for ($i = 0; $i -lt $result.Updates.Count; $i++) {
        $update = $result.Updates.Item($i)
        if ($wanted.ContainsKey([string]$update.Title)) {
            if (-not $update.EulaAccepted) {
                $update.EulaAccepted = $true
            }
            [void]$toInstall.Add($update)
        }
    }
    if ($toInstall.Count -eq 0) {
        $Sync.Ok = $true
        $Sync.Count = 0
        $Sync.Reboot = $false
        $Sync.Done = $true
        return
    }
    $downloader = $session.CreateUpdateDownloader()
    $downloader.Updates = $toInstall
    [void]$downloader.Download()
    $installer = $session.CreateUpdateInstaller()
    $installer.Updates = $toInstall
    $installResult = $installer.Install()
    $Sync.Ok = $true
    $Sync.Count = [int]$toInstall.Count
    $Sync.Reboot = [bool]$installResult.RebootRequired
    $Sync.ResultCode = [int]$installResult.ResultCode
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Open-WinToolUri {
    param(
        [Parameter(Mandatory = $true)][string]$Uri
    )
    if ($Uri -notmatch '^(https://|ms-settings:)') {
        Write-WinToolLog -Message (Get-WinToolText "msg.blocked-unexpected-link-n" $Uri) -Level "warn"
        return
    }
    try {
        Start-Process -FilePath $Uri | Out-Null
    }
    catch {
        Write-WinToolLog -Message (Get-WinToolText "msg.could-not-open-n-n" $Uri $_.Exception.Message) -Level "warn"
    }
}
# endregion

# region src/Private/Drivers.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Get-WinToolDriverCatalog {
    return (Get-WinToolCachedPayloadObject -Name "Drivers")
}

function ConvertTo-WinToolHardwareId {
    param([AllowEmptyString()][string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return "" }
    return $Text.Trim().ToUpperInvariant()
}

function ConvertTo-WinToolHardwareIdList {
    param($Value)
    $list = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    foreach ($item in @($Value)) {
        if ($null -eq $item) { continue }
        $nested = $false
        if ($item -is [System.Array]) { $nested = $true }
        elseif (($item -is [System.Collections.IEnumerable]) -and ($item -isnot [string])) { $nested = $true }
        if ($nested) {
            foreach ($inner in @($item)) {
                $key = ConvertTo-WinToolHardwareId -Text ([string]$inner)
                if (-not [string]::IsNullOrWhiteSpace($key) -and -not $seen.ContainsKey($key)) {
                    $seen[$key] = $true
                    $list.Add($key) | Out-Null
                }
            }
            continue
        }
        $key = ConvertTo-WinToolHardwareId -Text ([string]$item)
        if (-not [string]::IsNullOrWhiteSpace($key) -and -not $seen.ContainsKey($key)) {
            $seen[$key] = $true
            $list.Add($key) | Out-Null
        }
    }
    return $list.ToArray()
}

function Test-WinToolHardwareIdMatch {
    param(
        [string[]]$DeviceId,
        [string[]]$UpdateId
    )
    foreach ($update in @($UpdateId)) {
        $want = ConvertTo-WinToolHardwareId -Text $update
        if ([string]::IsNullOrWhiteSpace($want)) { continue }
        foreach ($device in @($DeviceId)) {
            $have = ConvertTo-WinToolHardwareId -Text $device
            if ([string]::IsNullOrWhiteSpace($have)) { continue }
            if ($have -eq $want) { return $true }
            # A Windows Update hardware ID is often a shorter, more general
            # form of the device's ID (no SUBSYS or REV suffix).
            if ($have.StartsWith($want)) { return $true }
        }
    }
    return $false
}

function ConvertTo-WinToolDriverDate {
    param($Value)
    if ($null -eq $Value -or [string]::IsNullOrWhiteSpace([string]$Value)) {
        return $null
    }
    if ($Value -is [datetime]) {
        return [datetime]$Value
    }
    $text = [string]$Value
    $parsed = [datetime]::MinValue
    if ([datetime]::TryParse($text, [ref]$parsed)) {
        return $parsed
    }
    if ($text -match '^\d{14}') {
        try {
            return [System.Management.ManagementDateTimeConverter]::ToDateTime($text)
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    return $null
}

function ConvertTo-WinToolDriverVersion {
    param([AllowEmptyString()][string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return $null }
    $trimmed = $Text.Trim()
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($piece in @($trimmed.Split("."))) {
        if ($piece -match '^[0-9]+$') { $parts.Add($piece) | Out-Null }
        else { break }
    }
    if ($parts.Count -lt 2) { return $null }
    while ($parts.Count -lt 2) { $parts.Add("0") | Out-Null }
    try { return [version]($parts.ToArray() -join ".") }
    catch { return $null }
}

function Compare-WinToolDriverVersion {
    param(
        [string]$Left,
        [string]$Right
    )
    $a = ConvertTo-WinToolDriverVersion -Text $Left
    $b = ConvertTo-WinToolDriverVersion -Text $Right
    if ($null -eq $a -or $null -eq $b) { return $null }
    return $a.CompareTo($b)
}

function Test-WinToolDriverNewer {
    param(
        $Update,
        $Device
    )
    $updateVersion = [string](Get-WinToolNote -Object $Update -Name "Version" -Default "")
    $deviceVersion = [string](Get-WinToolNote -Object $Device -Name "Version" -Default "")
    $compared = Compare-WinToolDriverVersion -Left $updateVersion -Right $deviceVersion
    if ($null -ne $compared) {
        return ($compared -gt 0)
    }
    $updateDate = ConvertTo-WinToolDriverDate -Value (Get-WinToolNote -Object $Update -Name "Date")
    $deviceDate = ConvertTo-WinToolDriverDate -Value (Get-WinToolNote -Object $Device -Name "Date")
    if ($null -ne $updateDate -and $null -ne $deviceDate) {
        return ($updateDate -gt $deviceDate)
    }
    # Windows Update is offering it (IsInstalled=0), so treat it as newer
    # when versions and dates cannot be compared.
    return $true
}

function Test-WinToolDriverSoftwareId {
    param([string]$InstanceId)
    $id = [string]$InstanceId
    return ($id -match '^(ROOT\\|SWD\\|UEFI\\|UMB\\|HTREE\\)')
}

function Test-WinToolDriverLikelyHardware {
    param(
        [string]$InstanceId,
        [string]$Class
    )
    $id = [string]$InstanceId
    if (Test-WinToolDriverSoftwareId -InstanceId $id) {
        return $false
    }
    if ($id -match '^(PCI\\|USB\\|HDAUDIO\\|DISPLAY\\|HID\\|SCSI\\|NVME\\|IDE\\|SD\\|ACPI\\PNP|SCSIADAPTER)') {
        return $true
    }
    $className = [string]$Class
    if ($className -match '^(Display|Net|Bluetooth|USB|HIDClass|Media|SCSIAdapter|HDC|Keyboard|Mouse|Monitor)$') {
        return $true
    }
    return $false
}

function Get-WinToolDriverProblemKind {
    param(
        [int]$Code,
        $Catalog
    )
    if ($null -eq $Catalog) {
        try { $Catalog = Get-WinToolDriverCatalog }
        catch { $Catalog = $null }
    }
    foreach ($item in @(Get-WinToolNote -Object $Catalog -Name "problem" -Default @())) {
        if ([int](Get-WinToolNote -Object $item -Name "code" -Default -1) -eq $Code) {
            return [string](Get-WinToolNote -Object $item -Name "kind" -Default "")
        }
    }
    switch ($Code) {
        1 { return "missing" }
        22 { return "disabled" }
        28 { return "missing" }
        31 { return "incompatible" }
        39 { return "incompatible" }
        43 { return "incompatible" }
        45 { return "ghost" }
        48 { return "incompatible" }
        52 { return "incompatible" }
    }
    return ""
}

function Get-WinToolDriverProblemName {
    param(
        [int]$Code,
        $Catalog
    )
    if ($null -eq $Catalog) { $Catalog = Get-WinToolDriverCatalog }
    foreach ($item in @(Get-WinToolNote -Object $Catalog -Name "problem" -Default @())) {
        if ([int](Get-WinToolNote -Object $item -Name "code" -Default -1) -eq $Code) {
            return [string](Get-WinToolNote -Object $item -Name "name" -Default "")
        }
    }
    if ($Code -gt 0) { return ("Problem code " + $Code) }
    return ""
}

function Test-WinToolDriverMissing {
    param($Device)
    $instanceId = [string](Get-WinToolNote -Object $Device -Name "InstanceId" -Default "")
    $class = [string](Get-WinToolNote -Object $Device -Name "Class" -Default "")
    # ROOT/SWD/UEFI software and leftover tree entries are not missing hardware,
    # even when Windows reports ConfigManagerErrorCode 1 or 28.
    if (Test-WinToolDriverSoftwareId -InstanceId $instanceId) { return $false }
    $code = [int](Get-WinToolNote -Object $Device -Name "Problem" -Default 0)
    $kind = Get-WinToolDriverProblemKind -Code $code
    $present = [bool](Get-WinToolNote -Object $Device -Name "Present" -Default $true)
    if (-not $present) { return $false }
    if ($kind -eq "ghost" -or $kind -eq "disabled") { return $false }
    if ($kind -eq "missing") { return $true }
    $version = [string](Get-WinToolNote -Object $Device -Name "Version" -Default "")
    $provider = [string](Get-WinToolNote -Object $Device -Name "Provider" -Default "")
    $hasDriver = (-not [string]::IsNullOrWhiteSpace($version) -or -not [string]::IsNullOrWhiteSpace($provider))
    if ($hasDriver) { return $false }
    return (Test-WinToolDriverLikelyHardware -InstanceId $instanceId -Class $class)
}

function Find-WinToolDriverUpdateMatch {
    param(
        [Parameter(Mandatory = $true)]$Device,
        $Update = @()
    )
    $ids = @(Get-WinToolNote -Object $Device -Name "HardwareId" -Default @())
    foreach ($item in @($Update)) {
        $updateIds = @(Get-WinToolNote -Object $item -Name "HardwareId" -Default @())
        if ((@($updateIds).Count -gt 0) -and (Test-WinToolHardwareIdMatch -DeviceId $ids -UpdateId $updateIds)) {
            return $item
        }
    }
    $name = [string](Get-WinToolNote -Object $Device -Name "Name" -Default "")
    if ([string]::IsNullOrWhiteSpace($name)) { return $null }
    foreach ($item in @($Update)) {
        $model = [string](Get-WinToolNote -Object $item -Name "Model" -Default "")
        $title = [string](Get-WinToolNote -Object $item -Name "Title" -Default "")
        if (-not [string]::IsNullOrWhiteSpace($model) -and $name.Equals($model, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $item
        }
        if (-not [string]::IsNullOrWhiteSpace($title) -and $title.IndexOf($name, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
            return $item
        }
    }
    return $null
}

function ConvertTo-WinToolDriverRow {
    param(
        [Parameter(Mandatory = $true)]$Device,
        [string]$Group,
        $Offer
    )
    $name = [string](Get-WinToolNote -Object $Device -Name "Name" -Default "")
    $class = [string](Get-WinToolNote -Object $Device -Name "Class" -Default "")
    $version = [string](Get-WinToolNote -Object $Device -Name "Version" -Default "")
    $date = ConvertTo-WinToolDriverDate -Value (Get-WinToolNote -Object $Device -Name "Date")
    $availableVersion = ""
    $availableDate = $null
    $title = ""
    if ($null -ne $Offer) {
        $availableVersion = [string](Get-WinToolNote -Object $Offer -Name "Version" -Default "")
        $availableDate = ConvertTo-WinToolDriverDate -Value (Get-WinToolNote -Object $Offer -Name "Date")
        $title = [string](Get-WinToolNote -Object $Offer -Name "Title" -Default "")
    }
    return [pscustomobject]@{
        Id               = [string](Get-WinToolNote -Object $Device -Name "InstanceId" -Default $name)
        Name             = $name
        Class            = $class
        Group            = $Group
        Kind             = "device"
        Version          = $version
        Date             = $date
        AvailableVersion = $availableVersion
        AvailableDate    = $availableDate
        Title            = $title
        Problem          = [int](Get-WinToolNote -Object $Device -Name "Problem" -Default 0)
        Provider         = [string](Get-WinToolNote -Object $Device -Name "Provider" -Default "")
        Present          = [bool](Get-WinToolNote -Object $Device -Name "Present" -Default $true)
        Selected         = ($Group -eq "outdated" -or $Group -eq "missing" -or $Group -eq "runtime" -or $Group -eq "gpu")
        WingetId         = ""
        Scope            = ""
        Checkbox         = $null
        Device           = $Device
        Offer            = $Offer
    }
}

function Set-WinToolDriverRowCheckbox {
    param(
        $Row,
        $Checkbox
    )
    if ($null -eq $Row) { return $Row }
    $property = $Row.PSObject.Properties["Checkbox"]
    if ($null -eq $property) {
        Add-Member -InputObject $Row -NotePropertyName "Checkbox" -NotePropertyValue $Checkbox -Force
    }
    else {
        $Row.Checkbox = $Checkbox
    }
    return $Row
}

function Get-WinToolDriverDeviceGroup {
    param(
        [Parameter(Mandatory = $true)]$Device,
        $Update = @()
    )
    $code = [int](Get-WinToolNote -Object $Device -Name "Problem" -Default 0)
    $kind = Get-WinToolDriverProblemKind -Code $code
    $present = [bool](Get-WinToolNote -Object $Device -Name "Present" -Default $true)
    if (-not $present -or $kind -eq "ghost") {
        return [pscustomobject]@{ Group = "ghost"; Offer = $null }
    }
    $offer = Find-WinToolDriverUpdateMatch -Device $Device -Update $Update
    if (Test-WinToolDriverMissing -Device $Device) {
        return [pscustomobject]@{ Group = "missing"; Offer = $offer }
    }
    if ($null -ne $offer -and (Test-WinToolDriverNewer -Update $offer -Device $Device)) {
        return [pscustomobject]@{ Group = "outdated"; Offer = $offer }
    }
    return [pscustomobject]@{ Group = "current"; Offer = $null }
}

function Get-WinToolDriverRuntimeRow {
    param(
        [Parameter(Mandatory = $true)]$Runtime,
        $Cache
    )
    if ($null -eq $Cache) { $Cache = Get-WinToolPackageCache }
    $id = [string](Get-WinToolNote -Object $Runtime -Name "wingetId" -Default "")
    $name = [string](Get-WinToolNote -Object $Runtime -Name "name" -Default $id)
    $ready = [bool]$Cache.WingetReady
    $installed = $false
    $upgrade = $false
    if ($ready -and -not [string]::IsNullOrWhiteSpace($id)) {
        $installed = Test-WinToolCachedWingetId -Id $id -Cache $Cache
        $upgrade = Test-WinToolCachedWingetUpgrade -Id $id -Cache $Cache
    }
    $group = "runtime-current"
    $selected = $false
    $available = ""
    $attention = $false
    if ($null -ne $Runtime.PSObject.Properties["attention"]) {
        $attention = [bool]$Runtime.attention
    }
    elseif ($null -ne $Runtime.PSObject.Properties["Attention"]) {
        $attention = [bool]$Runtime.Attention
    }
    if (-not $ready) {
        $group = "runtime-pending"
    }
    elseif ($upgrade) {
        $group = "runtime"
        $selected = $true
        $available = Get-WinToolText "drivers.runtime.updateAvailable"
    }
    elseif (-not $installed) {
        $group = "runtime"
        $selected = $true
        $available = Get-WinToolText "drivers.runtime.notInstalled"
    }
    return [pscustomobject]@{
        Id               = [string](Get-WinToolNote -Object $Runtime -Name "id" -Default $id)
        Name             = $name
        Class            = "Runtime"
        Group            = $group
        Kind             = "runtime"
        Version          = ""
        Date             = $null
        AvailableVersion = $available
        AvailableDate    = $null
        Title            = $name
        Problem          = 0
        Provider         = ""
        Present          = $true
        Selected         = $selected
        WingetId         = $id
        Scope            = [string](Get-WinToolNote -Object $Runtime -Name "scope" -Default "machine")
        Attention        = $attention
        Checkbox         = $null
        Device           = $null
        Offer            = $null
    }
}

function Get-WinToolDriverGpuRow {
    param(
        [string]$GpuName,
        $Catalog
    )
    if ($null -eq $Catalog) { $Catalog = Get-WinToolDriverCatalog }
    $vendor = Resolve-WinToolGpuVendor -Name $GpuName -Vendor @(Get-WinToolNote -Object $Catalog -Name "gpuApps" -Default @())
    if ($null -eq $vendor) { return $null }
    $cache = Get-WinToolPackageCache
    $id = [string]$vendor.wingetId
    $installed = $false
    $upgrade = $false
    if ([bool]$cache.WingetReady -and -not [string]::IsNullOrWhiteSpace($id)) {
        $installed = Test-WinToolCachedWingetId -Id $id -Cache $cache
        $upgrade = Test-WinToolCachedWingetUpgrade -Id $id -Cache $cache
    }
    $available = Get-WinToolText "drivers.runtime.official"
    if ($upgrade) { $available = Get-WinToolText "drivers.runtime.updateAvailable" }
    elseif ($installed) { $available = Get-WinToolText "drivers.runtime.installed" }
    return [pscustomobject]@{
        Id               = [string]$vendor.id
        Name             = ([string]$vendor.name + " for " + $GpuName)
        Class            = "Display"
        Group            = "gpu"
        Kind             = "gpu"
        Version          = ""
        Date             = $null
        AvailableVersion = $available
        AvailableDate    = $null
        Title            = [string]$vendor.name
        Problem          = 0
        Provider         = [string]$vendor.name
        Present          = $true
        Selected         = (-not $installed -or $upgrade)
        WingetId         = $id
        Scope            = "machine"
        Checkbox         = $null
        Device           = $null
        Offer            = $null
    }
}

function Group-WinToolDriverRow {
    param(
        $Device = @(),
        $Update = @(),
        $Runtime = $null,
        $GpuName = @(),
        $Cache,
        $Catalog
    )
    if ($null -eq $Catalog) { $Catalog = Get-WinToolDriverCatalog }
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Device)) {
        $present = [bool](Get-WinToolNote -Object $item -Name "Present" -Default $true)
        $kind = Get-WinToolDriverProblemKind -Code ([int](Get-WinToolNote -Object $item -Name "Problem" -Default 0))
        if (-not $present -or $kind -eq "ghost") { continue }
        $result = Get-WinToolDriverDeviceGroup -Device $item -Update $Update
        $rows.Add((ConvertTo-WinToolDriverRow -Device $item -Group ([string]$result.Group) -Offer $result.Offer)) | Out-Null
    }
    $runtimeItems = $Runtime
    if ($null -eq $runtimeItems) {
        $runtimeItems = @(Get-WinToolNote -Object $Catalog -Name "runtimes" -Default @())
    }
    foreach ($item in @($runtimeItems)) {
        $rows.Add((Get-WinToolDriverRuntimeRow -Runtime $item -Cache $Cache)) | Out-Null
    }
    foreach ($name in @($GpuName)) {
        $row = Get-WinToolDriverGpuRow -GpuName ([string]$name) -Catalog $Catalog
        if ($null -ne $row) { $rows.Add($row) | Out-Null }
    }
    return $rows.ToArray()
}

function Format-WinToolDriverDate {
    param($Value)
    $date = ConvertTo-WinToolDriverDate -Value $Value
    if ($null -eq $date) { return "" }
    return $date.ToString("d MMM yyyy", [System.Globalization.CultureInfo]::GetCultureInfo("en-US"))
}

function Format-WinToolDriverDetail {
    param($Row)
    $group = [string]$Row.Group
    if ($group -eq "outdated" -or $group -eq "missing" -or $group -eq "runtime" -or $group -eq "gpu") {
        $available = [string]$Row.AvailableVersion
        $dateText = Format-WinToolDriverDate -Value $Row.AvailableDate
        if (-not [string]::IsNullOrWhiteSpace($dateText) -and -not [string]::IsNullOrWhiteSpace($available) -and $available -notmatch 'available|installed|Official|Not ') {
            return (Get-WinToolText "drivers.available.versionDate" $available $dateText)
        }
        if (-not [string]::IsNullOrWhiteSpace($dateText)) {
            return (Get-WinToolText "drivers.available.date" $dateText)
        }
        if (-not [string]::IsNullOrWhiteSpace($available)) {
            return (Get-WinToolText "drivers.available.version" $available)
        }
        return (Get-WinToolText "drivers.available.wu")
    }
    $current = [string]$Row.Version
    $dateText = Format-WinToolDriverDate -Value $Row.Date
    if (-not [string]::IsNullOrWhiteSpace($current) -and -not [string]::IsNullOrWhiteSpace($dateText)) {
        return (Get-WinToolText "drivers.current.versionDate" $current $dateText)
    }
    if (-not [string]::IsNullOrWhiteSpace($dateText)) {
        return (Get-WinToolText "drivers.current.date" $dateText)
    }
    if (-not [string]::IsNullOrWhiteSpace($current)) {
        return (Get-WinToolText "drivers.current.version" $current)
    }
    return (Get-WinToolText "drivers.current.upToDate")
}

function Format-WinToolDriverHeader {
    param(
        [int]$Outdated = 0,
        [int]$Missing = 0,
        [int]$Runtime = 0
    )
    $head = ""
    if ($Outdated -gt 0 -and $Missing -gt 0) {
        $left = Get-WinToolCountText "drivers.header.both.left" $Outdated
        $right = Get-WinToolCountText "drivers.header.both.right" $Missing
        $head = Get-WinToolText "drivers.header.both" $left $right
    }
    elseif ($Outdated -gt 0) { $head = Get-WinToolCountText "drivers.header.outdated" $Outdated }
    elseif ($Missing -gt 0) { $head = Get-WinToolCountText "drivers.header.missing" $Missing }
    $extra = ""
    if ($Runtime -gt 0) {
        $extra = Get-WinToolCountText "drivers.header.runtime" $Runtime
    }
    if ([string]::IsNullOrWhiteSpace($head) -and [string]::IsNullOrWhiteSpace($extra)) {
        return (Get-WinToolText "drivers.header.none")
    }
    if ([string]::IsNullOrWhiteSpace($head)) { return $extra }
    if ([string]::IsNullOrWhiteSpace($extra)) { return $head }
    return ($head + " " + $extra)
}

function Format-WinToolDriverStatusSummary {
    param(
        [int]$Outdated = 0,
        [int]$Missing = 0,
        [int]$Runtime = 0
    )
    if ($Outdated -le 0 -and $Missing -le 0 -and $Runtime -le 0) {
        return (Get-WinToolText "status.summary.scanNone")
    }
    return (Get-WinToolText "status.summary.scan" $Outdated $Missing $Runtime)
}

function Test-WinToolDriverRuntimeAttention {
    param($Row)
    if ([string](Get-WinToolNote -Object $Row -Name "Kind" -Default "") -ne "runtime") {
        return $false
    }
    if ([string](Get-WinToolNote -Object $Row -Name "Group" -Default "") -ne "runtime") {
        return $false
    }
    if ([bool](Get-WinToolNote -Object $Row -Name "Attention" -Default $false)) {
        return $true
    }
    $available = [string](Get-WinToolNote -Object $Row -Name "AvailableVersion" -Default "")
    return ($available -eq (Get-WinToolText "drivers.runtime.updateAvailable"))
}

function Get-WinToolDriverAttentionRuntime {
    param($Row = @())
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Row)) {
        if (Test-WinToolDriverRuntimeAttention -Row $item) {
            $list.Add($item) | Out-Null
        }
    }
    return $list.ToArray()
}

function Get-WinToolDriverPcChip {
    param(
        $Info,
        $Display = @(),
        $Device = @()
    )
    $chips = New-Object System.Collections.Generic.List[object]
    function Add-Chip([string]$Key, [string]$Value) {
        if ([string]::IsNullOrWhiteSpace($Value)) { return }
        $chips.Add([pscustomobject]@{ Label = (Get-WinToolText $Key); Value = $Value }) | Out-Null
    }
    if ($null -ne $Info) {
        Add-Chip "drivers.chip.processor" ([string](Get-WinToolNote -Object $Info -Name "Cpu" -Default ""))
    }
    $network = ""
    foreach ($item in @($Device)) {
        $class = [string](Get-WinToolNote -Object $item -Name "Class" -Default "")
        $present = [bool](Get-WinToolNote -Object $item -Name "Present" -Default $true)
        $name = [string](Get-WinToolNote -Object $item -Name "Name" -Default "")
        if ($present -and $class -eq "Net" -and -not [string]::IsNullOrWhiteSpace($name) -and $name -notmatch 'Virtual|WAN Miniport|Bluetooth|Kernel Debug') {
            $network = $name
            break
        }
    }
    Add-Chip "drivers.chip.network" $network
    $displayName = ""
    foreach ($item in @($Display)) {
        $name = [string](Get-WinToolNote -Object $item -Name "Name" -Default "")
        if (-not [string]::IsNullOrWhiteSpace($name)) { $displayName = $name; break }
    }
    if ([string]::IsNullOrWhiteSpace($displayName) -and $null -ne $Info) {
        $displayName = [string](Get-WinToolNote -Object $Info -Name "Gpu" -Default "")
        if (-not [string]::IsNullOrWhiteSpace($displayName)) {
            Add-Chip "drivers.chip.graphics" $displayName
            $displayName = ""
        }
    }
    else {
        Add-Chip "drivers.chip.display" $displayName
    }
    if ($null -ne $Info) {
        Add-Chip "drivers.chip.system" ([string](Get-WinToolNote -Object $Info -Name "Os" -Default ""))
    }
    return $chips.ToArray()
}

function Get-WinToolDriverProblemDevice {
    param($Device = @())
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Device)) {
        $code = [int](Get-WinToolNote -Object $item -Name "Problem" -Default 0)
        $present = [bool](Get-WinToolNote -Object $item -Name "Present" -Default $true)
        if ($code -le 0) { continue }
        $kind = Get-WinToolDriverProblemKind -Code $code
        if ($kind -eq "ghost" -or -not $present) { continue }
        $list.Add($item) | Out-Null
    }
    return $list.ToArray()
}

function Get-WinToolDriverGhostDevice {
    param($Device = @())
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Device)) {
        $code = [int](Get-WinToolNote -Object $item -Name "Problem" -Default 0)
        $present = [bool](Get-WinToolNote -Object $item -Name "Present" -Default $true)
        $kind = Get-WinToolDriverProblemKind -Code $code
        if (-not $present -or $kind -eq "ghost") {
            $list.Add($item) | Out-Null
        }
    }
    return $list.ToArray()
}

function Get-WinToolDriverIncompatibleDevice {
    param(
        $Device = @(),
        [bool]$MemoryIntegrity = $false
    )
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Device)) {
        $code = [int](Get-WinToolNote -Object $item -Name "Problem" -Default 0)
        $kind = Get-WinToolDriverProblemKind -Code $code
        if ($kind -eq "incompatible") {
            $list.Add($item) | Out-Null
            continue
        }
        if ($MemoryIntegrity -and $code -eq 52) {
            $list.Add($item) | Out-Null
        }
    }
    return $list.ToArray()
}

function Format-WinToolMachineSummary {
    param($Info)
    if ($null -eq $Info) { return (Get-WinToolText "drivers.info.unavailable") }
    $lines = New-Object System.Collections.Generic.List[string]
    $map = [ordered]@{
        Os      = "drivers.info.os"
        Version = "drivers.info.version"
        Cpu     = "drivers.info.cpu"
        Gpu     = "drivers.info.gpu"
        Board   = "drivers.info.board"
        Memory  = "drivers.info.memory"
        Bios    = "drivers.info.bios"
    }
    foreach ($key in $map.Keys) {
        $value = [string](Get-WinToolNote -Object $Info -Name $key -Default "")
        if (-not [string]::IsNullOrWhiteSpace($value)) {
            $label = Get-WinToolText -Key ([string]$map[$key])
            $lines.Add(($label + ": " + $value)) | Out-Null
        }
    }
    if ($lines.Count -eq 0) { return (Get-WinToolText "drivers.info.unavailable") }
    return ($lines.ToArray() -join [Environment]::NewLine)
}

function Format-WinToolDisplayAdvice {
    param($Display)
    if ($null -eq $Display) {
        return (Get-WinToolText "drivers.display.none")
    }
    $name = [string](Get-WinToolNote -Object $Display -Name "Name" -Default (Get-WinToolText "drivers.display.this"))
    $currentWidth = [int](Get-WinToolNote -Object $Display -Name "Width" -Default 0)
    $currentHeight = [int](Get-WinToolNote -Object $Display -Name "Height" -Default 0)
    $nativeWidth = [int](Get-WinToolNote -Object $Display -Name "NativeWidth" -Default 0)
    $nativeHeight = [int](Get-WinToolNote -Object $Display -Name "NativeHeight" -Default 0)
    $gpu = [string](Get-WinToolNote -Object $Display -Name "Gpu" -Default "")
    $parts = New-Object System.Collections.Generic.List[string]
    if ($currentWidth -gt 0 -and $currentHeight -gt 0) {
        $parts.Add((Get-WinToolText "drivers.display.running" $name $currentWidth $currentHeight)) | Out-Null
    }
    else {
        $parts.Add((Get-WinToolText "drivers.display.found" $name)) | Out-Null
    }
    if ($nativeWidth -gt 0 -and $nativeHeight -gt 0) {
        if ($currentWidth -ne $nativeWidth -or $currentHeight -ne $nativeHeight) {
            $parts.Add((Get-WinToolText "drivers.display.preferred" $nativeWidth $nativeHeight)) | Out-Null
        }
        else {
            $parts.Add((Get-WinToolText "drivers.display.matches")) | Out-Null
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($gpu)) {
        $parts.Add((Get-WinToolText "drivers.display.gpu" $gpu)) | Out-Null
    }
    else {
        $parts.Add((Get-WinToolText "drivers.display.gpuGeneric")) | Out-Null
    }
    return ($parts.ToArray() -join " ")
}

function New-WinToolDriverDeviceRecord {
    param(
        [string]$Name,
        [string]$Class,
        [string]$InstanceId,
        [int]$Problem = 0,
        [bool]$Present = $true,
        [string]$Version = "",
        [string]$Provider = "",
        $Date = $null,
        $HardwareId = @(),
        [string]$Inf = ""
    )
    return [pscustomobject]@{
        Name       = $Name
        Class      = $Class
        InstanceId = $InstanceId
        Problem    = $Problem
        Present    = $Present
        Version    = $Version
        Provider   = $Provider
        Date       = $Date
        HardwareId = @(ConvertTo-WinToolHardwareIdList -Value $HardwareId)
        Inf        = $Inf
    }
}

function New-WinToolDriverUpdateRecord {
    param(
        [string]$Title,
        [string]$Model = "",
        [string]$Version = "",
        $Date = $null,
        $HardwareId = @()
    )
    return [pscustomobject]@{
        Title      = $Title
        Model      = $Model
        Version    = $Version
        Date       = $Date
        HardwareId = @(ConvertTo-WinToolHardwareIdList -Value $HardwareId)
    }
}

function Get-WinToolDriverScanScript {
    $scriptText = @'
param($Sync)
$ErrorActionPreference = "Stop"
$Sync.Cancel = [bool]$Sync.Cancel
$Sync.Phase = "devices"
function Convert-WinToolJobDate($Value) {
    if ($null -eq $Value) { return "" }
    try {
        if ($Value -is [datetime]) { return ([datetime]$Value).ToString("o") }
        $text = [string]$Value
        if ($text -match '^\d{14}') {
            return ([System.Management.ManagementDateTimeConverter]::ToDateTime($text)).ToString("o")
        }
        $parsed = [datetime]::MinValue
        if ([datetime]::TryParse($text, [ref]$parsed)) { return $parsed.ToString("o") }
    }
    catch { }
    return [string]$Value
}
try {
    $devices = New-Object System.Collections.Generic.List[object]
    $signed = @{}
    try {
        foreach ($row in @(Get-CimInstance -ClassName Win32_PnPSignedDriver -ErrorAction Stop)) {
            $key = [string]$row.DeviceID
            if ([string]::IsNullOrWhiteSpace($key)) { continue }
            $signed[$key.ToUpperInvariant()] = $row
        }
    }
    catch { }
    $entities = @()
    try { $entities = @(Get-CimInstance -ClassName Win32_PnPEntity -ErrorAction Stop) }
    catch { $entities = @() }
    foreach ($entity in $entities) {
        $instance = [string]$entity.DeviceID
        if ([string]::IsNullOrWhiteSpace($instance)) { $instance = [string]$entity.PNPDeviceID }
        if ([string]::IsNullOrWhiteSpace($instance)) { continue }
        $name = [string]$entity.Name
        if ([string]::IsNullOrWhiteSpace($name)) { $name = [string]$entity.Caption }
        if ([string]::IsNullOrWhiteSpace($name)) { $name = $instance }
        $code = 0
        if ($null -ne $entity.ConfigManagerErrorCode) { $code = [int]$entity.ConfigManagerErrorCode }
        $present = $true
        if ($code -eq 45) { $present = $false }
        if ($null -ne $entity.PSObject.Properties["Present"] -and $null -ne $entity.Present) {
            $present = [bool]$entity.Present
        }
        $hardware = @()
        if ($null -ne $entity.HardwareID) { $hardware += @($entity.HardwareID) }
        if ($null -ne $entity.CompatibleID) { $hardware += @($entity.CompatibleID) }
        if ($null -ne $entity.PNPDeviceID -and -not [string]::IsNullOrWhiteSpace([string]$entity.PNPDeviceID)) { $hardware += [string]$entity.PNPDeviceID }
        $driver = $null
        $lookup = $instance.ToUpperInvariant()
        if ($signed.ContainsKey($lookup)) { $driver = $signed[$lookup] }
        $version = ""
        $provider = ""
        $date = ""
        $inf = ""
        if ($null -ne $driver) {
            $version = [string]$driver.DriverVersion
            $provider = [string]$driver.Manufacturer
            if ([string]::IsNullOrWhiteSpace($provider)) { $provider = [string]$driver.DriverProviderName }
            $date = Convert-WinToolJobDate $driver.DriverDate
            if ($null -ne $driver.HardWareID -and -not [string]::IsNullOrWhiteSpace([string]$driver.HardWareID)) {
                $hardware += [string]$driver.HardWareID
            }
            if ($null -ne $driver.InfName) { $inf = [string]$driver.InfName }
        }
        $devices.Add([pscustomobject]@{
            Name = $name
            Class = [string]$entity.PNPClass
            InstanceId = $instance
            Problem = $code
            Present = $present
            Version = $version
            Provider = $provider
            Date = $date
            HardwareId = @($hardware | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim().ToUpperInvariant() } | Select-Object -Unique)
            Inf = $inf
        }) | Out-Null
    }

    if ($Sync.Cancel) {
        $Sync.Ok = $false
        $Sync.Error = "Cancelled"
        $Sync.Done = $true
        return
    }
    $Sync.Phase = "updates"
    $updates = New-Object System.Collections.Generic.List[object]
    try {
        $session = New-Object -ComObject Microsoft.Update.Session
        $searcher = $session.CreateUpdateSearcher()
        $result = $searcher.Search("IsInstalled=0 and Type='Driver'")
        for ($i = 0; $i -lt $result.Updates.Count; $i++) {
            $update = $result.Updates.Item($i)
            $ids = @()
            foreach ($name in @("DriverHardwareID", "DriverHardwareId")) {
                if ($null -ne $update.PSObject.Properties[$name] -and $null -ne $update.$name) {
                    $ids += @($update.$name)
                }
            }
            $version = ""
            if ($null -ne $update.PSObject.Properties["DriverVerVersion"]) { $version = [string]$update.DriverVerVersion }
            $date = ""
            if ($null -ne $update.PSObject.Properties["DriverVerDate"]) { $date = Convert-WinToolJobDate $update.DriverVerDate }
            $model = ""
            if ($null -ne $update.PSObject.Properties["DriverModel"]) { $model = [string]$update.DriverModel }
            $updates.Add([pscustomobject]@{
                Title = (([string]$update.Title) -replace "[\r\n\t]", " ")
                Model = $model
                Version = $version
                Date = $date
                HardwareId = @($ids | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim().ToUpperInvariant() } | Select-Object -Unique)
            }) | Out-Null
        }
    }
    catch {
        if ($devices.Count -eq 0) { throw }
        $Sync.Warning = $_.Exception.Message
    }

    if ($Sync.Cancel) {
        $Sync.Ok = $false
        $Sync.Error = "Cancelled"
        $Sync.Done = $true
        return
    }
    $Sync.Phase = "runtimes"
    $displays = New-Object System.Collections.Generic.List[object]
    try {
        foreach ($gpu in @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop)) {
            if ([string]::IsNullOrWhiteSpace([string]$gpu.Name)) { continue }
            $width = 0
            $height = 0
            if ($null -ne $gpu.CurrentHorizontalResolution) { $width = [int]$gpu.CurrentHorizontalResolution }
            if ($null -ne $gpu.CurrentVerticalResolution) { $height = [int]$gpu.CurrentVerticalResolution }
            $displays.Add([pscustomobject]@{
                Name = [string]$gpu.Name
                Gpu = [string]$gpu.Name
                Width = $width
                Height = $height
                NativeWidth = $width
                NativeHeight = $height
            }) | Out-Null
        }
    }
    catch { }

    try {
        $monitors = @(Get-CimInstance -Namespace root\wmi -ClassName WmiMonitorBasicDisplayParams -ErrorAction Stop)
        $index = 0
        foreach ($monitor in $monitors) {
            $nativeWidth = 0
            $nativeHeight = 0
            if ($null -ne $monitor.MaxHorizontalImageSize -and $null -ne $monitor.MaxVerticalImageSize) {
                # Physical size in cm is not a pixel resolution; leave native
                # at the current mode unless a better source is present.
            }
            $index++
        }
        $modes = @(Get-CimInstance -Namespace root\wmi -ClassName WmiMonitorListedSupportedSourceModes -ErrorAction SilentlyContinue)
        foreach ($item in @($modes)) {
            $bestW = 0
            $bestH = 0
            try {
                foreach ($mode in @($item.MonitorSourceModes)) {
                    $w = 0; $h = 0
                    if ($null -ne $mode.HorizontalActivePixels) { $w = [int]$mode.HorizontalActivePixels }
                    if ($null -ne $mode.VerticalActivePixels) { $h = [int]$mode.VerticalActivePixels }
                    if (($w * $h) -gt ($bestW * $bestH)) { $bestW = $w; $bestH = $h }
                }
            }
            catch { }
            if ($bestW -gt 0 -and $displays.Count -gt 0) {
                $displays[0].NativeWidth = $bestW
                $displays[0].NativeHeight = $bestH
            }
        }
    }
    catch { }

    $hvci = $false
    try {
        $guard = Get-CimInstance -Namespace root\Microsoft\Windows\DeviceGuard -ClassName Win32_DeviceGuard -ErrorAction Stop
        if (@($guard.SecurityServicesRunning) -contains 2) { $hvci = $true }
    }
    catch {
        try {
            $item = Get-ItemProperty -LiteralPath "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" -ErrorAction Stop
            if ([int]$item.Enabled -eq 1) { $hvci = $true }
        }
        catch { }
    }

    if ($devices.Count -gt 0) { $Sync.DeviceJson = ($devices.ToArray() | ConvertTo-Json -Compress -Depth 5) }
    else { $Sync.DeviceJson = "[]" }
    if ($updates.Count -gt 0) { $Sync.UpdateJson = ($updates.ToArray() | ConvertTo-Json -Compress -Depth 5) }
    else { $Sync.UpdateJson = "[]" }
    if ($displays.Count -gt 0) { $Sync.DisplayJson = ($displays.ToArray() | ConvertTo-Json -Compress -Depth 5) }
    else { $Sync.DisplayJson = "[]" }
    $Sync.Hvci = $hvci
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function ConvertFrom-WinToolJsonArray {
    param([AllowEmptyString()][string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text) -or $Text.Trim() -eq "[]") { return @() }
    $parsed = ConvertFrom-WinToolJsonText -Text $Text
    return @($parsed)
}

function ConvertFrom-WinToolDriverScan {
    param(
        [AllowEmptyString()][string]$DeviceJson,
        [AllowEmptyString()][string]$UpdateJson
    )
    $devices = New-Object System.Collections.Generic.List[object]
    foreach ($item in @(ConvertFrom-WinToolJsonArray -Text $DeviceJson)) {
        $devices.Add((New-WinToolDriverDeviceRecord `
                    -Name ([string](Get-WinToolNote -Object $item -Name "Name" -Default "")) `
                    -Class ([string](Get-WinToolNote -Object $item -Name "Class" -Default "")) `
                    -InstanceId ([string](Get-WinToolNote -Object $item -Name "InstanceId" -Default "")) `
                    -Problem ([int](Get-WinToolNote -Object $item -Name "Problem" -Default 0)) `
                    -Present ([bool](Get-WinToolNote -Object $item -Name "Present" -Default $true)) `
                    -Version ([string](Get-WinToolNote -Object $item -Name "Version" -Default "")) `
                    -Provider ([string](Get-WinToolNote -Object $item -Name "Provider" -Default "")) `
                    -Date (Get-WinToolNote -Object $item -Name "Date") `
                    -HardwareId @(Get-WinToolNote -Object $item -Name "HardwareId" -Default @()))) | Out-Null
    }
    $updates = New-Object System.Collections.Generic.List[object]
    foreach ($item in @(ConvertFrom-WinToolJsonArray -Text $UpdateJson)) {
        $updates.Add((New-WinToolDriverUpdateRecord `
                    -Title ([string](Get-WinToolNote -Object $item -Name "Title" -Default "")) `
                    -Model ([string](Get-WinToolNote -Object $item -Name "Model" -Default "")) `
                    -Version ([string](Get-WinToolNote -Object $item -Name "Version" -Default "")) `
                    -Date (Get-WinToolNote -Object $item -Name "Date") `
                    -HardwareId @(Get-WinToolNote -Object $item -Name "HardwareId" -Default @()))) | Out-Null
    }
    return [pscustomobject]@{
        Device = $devices.ToArray()
        Update = $updates.ToArray()
    }
}

function Get-WinToolDriverBackupScript {
    $scriptText = @'
param($Sync, $Folder)
$ErrorActionPreference = "Stop"
try {
    if ([string]::IsNullOrWhiteSpace($Folder)) { throw "No folder was chosen." }
    if (-not (Test-Path -LiteralPath $Folder)) {
        New-Item -ItemType Directory -Path $Folder -Force | Out-Null
    }
    $exporter = Get-Command -Name Export-WindowsDriver -ErrorAction SilentlyContinue
    if ($null -ne $exporter) {
        Export-WindowsDriver -Online -Destination $Folder | Out-Null
    }
    else {
        $pnputil = Join-Path $env:SystemRoot "System32\pnputil.exe"
        & $pnputil /export-driver * $Folder
        if ($LASTEXITCODE -ne 0) { throw "pnputil could not export the drivers (exit $LASTEXITCODE)." }
    }
    $count = @(Get-ChildItem -LiteralPath $Folder -Filter "*.inf" -Recurse -File -ErrorAction SilentlyContinue).Count
    $Sync.Count = $count
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolDriverOfflineScript {
    $scriptText = @'
param($Sync, $Folder)
$ErrorActionPreference = "Stop"
try {
    if ([string]::IsNullOrWhiteSpace($Folder) -or -not (Test-Path -LiteralPath $Folder)) {
        throw "The backup folder was not found."
    }
    $pnputil = Join-Path $env:SystemRoot "System32\pnputil.exe"
    $pattern = Join-Path $Folder "*.inf"
    & $pnputil /add-driver $pattern /subdirs /install
    $Sync.ExitCode = [int]$LASTEXITCODE
    if ($LASTEXITCODE -ne 0 -and $LASTEXITCODE -ne 3010 -and $LASTEXITCODE -ne 259) {
        throw "pnputil could not install the drivers (exit $LASTEXITCODE)."
    }
    $Sync.Reboot = ($LASTEXITCODE -eq 3010)
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolDriverAudioScript {
    $scriptText = @'
param($Sync)
$ErrorActionPreference = "Continue"
$log = New-Object System.Collections.Generic.List[string]
try {
    foreach ($name in @("AudioEndpointBuilder", "Audiosrv")) {
        try {
            Restart-Service -Name $name -Force -ErrorAction Stop
            $log.Add("Restarted $name.")
        }
        catch { $log.Add("Could not restart ${name}: $($_.Exception.Message)") }
    }
    $enabled = 0
    $devices = @()
    try { $devices = @(Get-PnpDevice -ErrorAction Stop) } catch { $devices = @() }
    foreach ($device in $devices) {
        $className = [string]$device.Class
        $status = [string]$device.Status
        if ($status -ne "Error" -and $status -ne "Unknown" -and $status -ne "Disabled" -and $status -ne "Degraded") { continue }
        if ($className -notmatch '^(MEDIA|AudioEndpoint|System)$' -and [string]$device.FriendlyName -notmatch '(?i)audio|sound|speaker|headphone') { continue }
        if ($status -eq "OK") { continue }
        try {
            Enable-PnpDevice -InstanceId ([string]$device.InstanceId) -Confirm:$false -ErrorAction Stop
            $enabled++
            $log.Add("Re-enabled " + [string]$device.FriendlyName + ".")
        }
        catch { $log.Add("Could not enable " + [string]$device.FriendlyName + ": " + $_.Exception.Message) }
    }
    $troubleshooter = Join-Path $env:SystemRoot "System32\msdt.exe"
    if (Test-Path -LiteralPath $troubleshooter) {
        Start-Process -FilePath $troubleshooter -ArgumentList @("/id", "AudioPlaybackDiagnostic") | Out-Null
        $log.Add("Opened the audio troubleshooter.")
    }
    else {
        Start-Process "ms-settings:sound" | Out-Null
        $log.Add("Opened Sound settings.")
    }
    $Sync.Log = $log.ToArray()
    $Sync.Enabled = $enabled
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
    $Sync.Log = $log.ToArray()
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolDriverNetworkScript {
    $scriptText = @'
param($Sync)
$ErrorActionPreference = "Continue"
$log = New-Object System.Collections.Generic.List[string]
try {
    $netsh = Join-Path $env:SystemRoot "System32\netsh.exe"
    $ipconfig = Join-Path $env:SystemRoot "System32\ipconfig.exe"
    & $netsh winsock reset | Out-Null
    $log.Add("Reset the Winsock catalog.")
    & $netsh int ip reset | Out-Null
    $log.Add("Reset the TCP/IP stack.")
    & $ipconfig /flushdns | Out-Null
    $log.Add("Flushed the DNS cache.")
    try {
        $adapters = @(Get-NetAdapter -ErrorAction Stop | Where-Object { $_.Status -eq "Up" -or $_.Status -eq "Disconnected" })
        foreach ($adapter in $adapters) {
            try {
                Restart-NetAdapter -Name $adapter.Name -Confirm:$false -ErrorAction Stop
                $log.Add("Restarted adapter " + $adapter.Name + ".")
            }
            catch { $log.Add("Could not restart " + $adapter.Name + ": " + $_.Exception.Message) }
        }
    }
    catch { $log.Add("Could not restart network adapters: $($_.Exception.Message)") }
    & $ipconfig /release | Out-Null
    & $ipconfig /renew | Out-Null
    $log.Add("Released and renewed IP addresses.")
    $Sync.Log = $log.ToArray()
    $Sync.Reboot = $true
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
    $Sync.Log = $log.ToArray()
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolDriverRemoveScript {
    $scriptText = @'
param($Sync, $IdText)
$ErrorActionPreference = "Continue"
$log = New-Object System.Collections.Generic.List[string]
$removed = 0
$failed = 0
try {
    $pnputil = Join-Path $env:SystemRoot "System32\pnputil.exe"
    foreach ($id in @(([string]$IdText) -split "`n")) {
        $instance = [string]$id
        if ([string]::IsNullOrWhiteSpace($instance)) { continue }
        & $pnputil /remove-device $instance
        if ($LASTEXITCODE -eq 0) {
            $removed++
            $log.Add("Removed $instance.")
        }
        else {
            $failed++
            $log.Add("Could not remove $instance (exit $LASTEXITCODE).")
        }
    }
    $Sync.Removed = $removed
    $Sync.Failed = $failed
    $Sync.Log = $log.ToArray()
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
    $Sync.Log = $log.ToArray()
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolDriverRescanScript {
    $scriptText = @'
param($Sync)
$ErrorActionPreference = "Stop"
try {
    $pnputil = Join-Path $env:SystemRoot "System32\pnputil.exe"
    & $pnputil /scan-devices
    if ($LASTEXITCODE -ne 0) { throw "pnputil could not rescan devices (exit $LASTEXITCODE)." }
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolDriverToggleScript {
    $scriptText = @'
param($Sync, $IdText, $Action)
$ErrorActionPreference = "Continue"
$log = New-Object System.Collections.Generic.List[string]
$count = 0
try {
    foreach ($id in @(([string]$IdText) -split "`n")) {
        if ([string]::IsNullOrWhiteSpace($id)) { continue }
        try {
            if ($Action -eq "enable") {
                Enable-PnpDevice -InstanceId $id -Confirm:$false -ErrorAction Stop
                $log.Add("Enabled $id.")
            }
            else {
                Disable-PnpDevice -InstanceId $id -Confirm:$false -ErrorAction Stop
                $log.Add("Disabled $id.")
            }
            $count++
        }
        catch { $log.Add("Could not change ${id}: $($_.Exception.Message)") }
    }
    $Sync.Count = $count
    $Sync.Log = $log.ToArray()
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
    $Sync.Log = $log.ToArray()
}
$Sync.Done = $true
'@
    return $scriptText
}

function Get-WinToolDriverInfoScript {
    $scriptText = @'
param($Sync)
$ErrorActionPreference = "Continue"
$info = @{ Os = ""; Version = ""; Cpu = ""; Gpu = ""; Board = ""; Memory = ""; Bios = "" }
try {
    try {
        $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $info.Os = ([string]$os.Caption -replace '^Microsoft\s+', '').Trim()
        $gb = [math]::Round(([double]$os.TotalVisibleMemorySize * 1KB) / 1GB, 1)
        if ($gb -gt 0) { $info.Memory = ("{0} GB" -f $gb) }
    } catch { }
    try { $info.Version = [string](Get-ItemProperty -LiteralPath "HKLM:\Software\Microsoft\Windows NT\CurrentVersion" -ErrorAction Stop).DisplayVersion } catch { }
    try { $info.Cpu = [string](@(Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop)[0].Name).Trim() } catch { }
    try {
        $gpus = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.Name) } | ForEach-Object { [string]$_.Name })
        if ($gpus.Count -gt 0) { $info.Gpu = ($gpus -join ", ") }
    } catch { }
    try {
        $board = Get-CimInstance -ClassName Win32_BaseBoard -ErrorAction Stop
        $info.Board = (([string]$board.Manufacturer).Trim() + " " + ([string]$board.Product).Trim()).Trim()
    } catch { }
    try {
        $modules = @(Get-CimInstance -ClassName Win32_PhysicalMemory -ErrorAction Stop)
        $total = [double]0
        foreach ($module in $modules) { $total += [double]$module.Capacity }
        if ($total -gt 0) { $info.Memory = ("{0} GB" -f [math]::Round($total / 1GB, 1)) }
    } catch { }
    try {
        $bios = Get-CimInstance -ClassName Win32_BIOS -ErrorAction Stop
        $info.Bios = (([string]$bios.Manufacturer).Trim() + " " + ([string]$bios.SMBIOSBIOSVersion).Trim()).Trim()
    } catch { }
    $Sync.Info = [pscustomobject]$info
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Test-WinToolDriverCatalog {
    param(
        $Catalog,
        $Errors
    )
    if ([int](Get-WinToolNote -Object $Catalog -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $Errors -Message "drivers.json schemaVersion must be 1."
    }
    $ids = @{}
    $runtimes = @(Get-WinToolNote -Object $Catalog -Name "runtimes" -Default @())
    if ($runtimes.Count -eq 0) {
        Add-WinToolDataError -Errors $Errors -Message "drivers.json has no game runtimes."
    }
    foreach ($item in $runtimes) {
        $id = [string](Get-WinToolNote -Object $item -Name "id" -Default "")
        $name = [string](Get-WinToolNote -Object $item -Name "name" -Default "")
        $wingetId = [string](Get-WinToolNote -Object $item -Name "wingetId" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($name)) {
            Add-WinToolDataError -Errors $Errors -Message (Get-WinToolText "msg.a-game-runtime-is-missing-an-id-or-name")
        }
        if ($ids.ContainsKey($id)) {
            Add-WinToolDataError -Errors $Errors -Message (Get-WinToolText "msg.duplicate-driver-catalog-id-n" $id)
        }
        else {
            $ids[$id] = $true
        }
        if (-not (Test-WinToolWingetId -Id $wingetId)) {
            Add-WinToolDataError -Errors $Errors -Message (Get-WinToolText "msg.runtime-n-has-an-unexpected-winget-id-n" $id $wingetId)
        }
        $scope = [string](Get-WinToolNote -Object $item -Name "scope" -Default "")
        if (-not [string]::IsNullOrWhiteSpace($scope) -and @("user", "machine") -notcontains $scope) {
            Add-WinToolDataError -Errors $Errors -Message (Get-WinToolText "msg.runtime-n-has-an-unknown-scope" $id)
        }
    }
    $attentionCount = @($runtimes | Where-Object { [bool](Get-WinToolNote -Object $_ -Name "attention" -Default $false) }).Count
    if ($attentionCount -lt 1) {
        Add-WinToolDataError -Errors $Errors -Message "drivers.json should mark at least one recommended game runtime with attention."
    }
    $apps = @(Get-WinToolNote -Object $Catalog -Name "gpuApps" -Default @())
    if ($apps.Count -lt 3) {
        Add-WinToolDataError -Errors $Errors -Message "drivers.json should list the official AMD, NVIDIA, and Intel apps."
    }
    foreach ($item in $apps) {
        $id = [string](Get-WinToolNote -Object $item -Name "id" -Default "")
        $name = [string](Get-WinToolNote -Object $item -Name "name" -Default "")
        $wingetId = [string](Get-WinToolNote -Object $item -Name "wingetId" -Default "")
        $match = @(Get-WinToolNote -Object $item -Name "match" -Default @())
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($name) -or $match.Count -eq 0) {
            Add-WinToolDataError -Errors $Errors -Message (Get-WinToolText "msg.a-graphics-app-is-missing-an-id-name-or-match-list")
        }
        if (-not (Test-WinToolWingetId -Id $wingetId)) {
            Add-WinToolDataError -Errors $Errors -Message (Get-WinToolText "msg.graphics-app-n-has-an-unexpected-winget-id-n" $id $wingetId)
        }
    }
    $codes = @{}
    foreach ($item in @(Get-WinToolNote -Object $Catalog -Name "problem" -Default @())) {
        $code = [int](Get-WinToolNote -Object $item -Name "code" -Default -1)
        $name = [string](Get-WinToolNote -Object $item -Name "name" -Default "")
        $kind = [string](Get-WinToolNote -Object $item -Name "kind" -Default "")
        if ($code -le 0 -or [string]::IsNullOrWhiteSpace($name) -or @("missing", "disabled", "ghost", "incompatible") -notcontains $kind) {
            Add-WinToolDataError -Errors $Errors -Message (Get-WinToolText "msg.a-problem-code-entry-is-missing-a-code-name-or-known-kin")
        }
        if ($codes.ContainsKey($code)) {
            Add-WinToolDataError -Errors $Errors -Message (Get-WinToolText "msg.duplicate-problem-code-n" $code)
        }
        else {
            $codes[$code] = $true
        }
    }
    foreach ($needed in @(1, 22, 28, 31, 39, 43, 45, 48, 52)) {
        if (-not $codes.ContainsKey($needed)) {
            Add-WinToolDataError -Errors $Errors -Message "drivers.json is missing problem code $needed."
        }
    }
}

function Get-WinToolDriverRollbackScript {
    return @'
param($Sync, $Inf)
$ErrorActionPreference = "Stop"
try {
    $output = & pnputil.exe /rollback-driver $Inf 2>&1 | ForEach-Object { "$_" }
    $Sync.Log = @($output)
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
}
# endregion

# region src/Private/UpdateModes.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# Windows Update modes from data/updates.json. A mode is a set of policy
# values under HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate plus a
# startup type for the update services. Applying a mode first clears every
# policy value any mode knows about, so switching modes never stacks, and
# "Default" is the revert.

$script:WinToolUpdatePolicyRoot = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
$script:WinToolServiceStartTypes = @("Manual", "Automatic", "AutomaticDelayed", "Disabled")

function Get-WinToolUpdateMode {
    param(
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    return @(Get-WinToolNote -Object $Catalog -Name "modes" -Default @())
}

function Find-WinToolUpdateMode {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    foreach ($mode in (Get-WinToolUpdateMode -Catalog $Catalog)) {
        if ([string]$mode.id -eq $Id) {
            return $mode
        }
    }
    return $null
}

function Get-WinToolUpdatePolicyKey {
    param(
        [Parameter(Mandatory = $true)]$Policy
    )
    return ([string]$Policy.path + "|" + [string]$Policy.name).ToLowerInvariant()
}

function Get-WinToolManagedUpdatePolicy {
    param(
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    # Every policy value any mode sets, once each.
    $seen = @{}
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($mode in (Get-WinToolUpdateMode -Catalog $Catalog)) {
        foreach ($policy in @(Get-WinToolNote -Object $mode -Name "policies" -Default @())) {
            $key = Get-WinToolUpdatePolicyKey -Policy $policy
            if (-not $seen.ContainsKey($key)) {
                $seen[$key] = $true
                $list.Add([pscustomobject]@{ path = [string]$policy.path; name = [string]$policy.name })
            }
        }
    }
    return $list.ToArray()
}

function Get-WinToolUpdateModeChange {
    param(
        [Parameter(Mandatory = $true)][string]$ModeId,
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    $mode = Find-WinToolUpdateMode -Id $ModeId -Catalog $Catalog
    if ($null -eq $mode) {
        throw (Get-WinToolText "msg.unknown-update-mode-n" $ModeId)
    }
    $set = New-Object System.Collections.Generic.List[object]
    foreach ($policy in @(Get-WinToolNote -Object $mode -Name "policies" -Default @())) {
        $set.Add([pscustomobject]@{ path = [string]$policy.path; name = [string]$policy.name; value = [int]$policy.value })
    }
    $services = New-Object System.Collections.Generic.List[object]
    foreach ($service in @(Get-WinToolNote -Object $mode -Name "services" -Default @())) {
        $services.Add([pscustomobject]@{
            name = [string]$service.name
            startupType = [string]$service.startupType
            stop = [bool](Get-WinToolNote -Object $service -Name "stop" -Default $false)
        })
    }
    return [pscustomobject]@{
        Mode = [string]$mode.id
        Name = [string]$mode.name
        Remove = @(Get-WinToolManagedUpdatePolicy -Catalog $Catalog)
        Set = $set.ToArray()
        Services = $services.ToArray()
    }
}

function Get-WinToolUpdateModeScript {
    param(
        [Parameter(Mandatory = $true)][string]$ModeId,
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    $change = Get-WinToolUpdateModeChange -ModeId $ModeId -Catalog $Catalog
    $json = ConvertTo-Json -InputObject $change -Depth 6 -Compress
    $body = @'
$ErrorActionPreference = "Stop"
$change = ConvertFrom-Json -InputObject '__CHANGE__'
$failed = 0
foreach ($item in @($change.Remove)) {
    if ((Test-Path -LiteralPath $item.path) -and ($null -ne (Get-ItemProperty -LiteralPath $item.path -Name $item.name -ErrorAction SilentlyContinue))) {
        Remove-ItemProperty -LiteralPath $item.path -Name $item.name
        Write-Output ("Removed policy " + $item.name)
    }
}
foreach ($item in @($change.Set)) {
    if (-not (Test-Path -LiteralPath $item.path)) {
        New-Item -Path $item.path -Force | Out-Null
    }
    New-ItemProperty -LiteralPath $item.path -Name $item.name -Value ([int]$item.value) -PropertyType DWord -Force | Out-Null
    Write-Output ("Set policy {0} = {1}" -f $item.name, $item.value)
}
$startNames = @{ Manual = "demand"; Automatic = "auto"; AutomaticDelayed = "delayed-auto"; Disabled = "disabled" }
foreach ($service in @($change.Services)) {
    if ($null -eq (Get-Service -Name $service.name -ErrorAction SilentlyContinue)) {
        Write-Output ("Service {0} is not on this PC." -f $service.name)
        continue
    }
    if ($service.stop) {
        try {
            Stop-Service -Name $service.name -Force -ErrorAction Stop
            Write-Output ("Stopped " + $service.name)
        }
        catch {
            Write-Output ("Could not stop {0}: {1}" -f $service.name, $_.Exception.Message)
        }
    }
    $output = & sc.exe config $service.name start= $startNames[[string]$service.startupType] 2>&1
    if ($LASTEXITCODE -eq 0) {
        Write-Output ("{0} startup is now {1}" -f $service.name, $service.startupType)
    }
    else {
        $failed++
        Write-Output ("Could not change {0}: {1}" -f $service.name, (($output | Out-String).Trim()))
    }
}
Write-Output ("Update mode is now: " + $change.Name)
if ($failed -gt 0) {
    exit 2
}
'@
    return $body.Replace("__CHANGE__", $json.Replace("'", "''"))
}

function Get-WinToolUpdateModePlan {
    param(
        [Parameter(Mandatory = $true)][string]$ModeId,
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    $mode = Find-WinToolUpdateMode -Id $ModeId -Catalog $Catalog
    if ($null -eq $mode) {
        throw (Get-WinToolText "msg.unknown-update-mode-n" $ModeId)
    }
    return @([pscustomobject]@{
        Type = "inline-script"
        Label = "Set Windows Update to: " + [string]$mode.name
        Name = "update-mode"
        Text = (Get-WinToolUpdateModeScript -ModeId $ModeId -Catalog $Catalog)
    })
}

function Get-WinToolUpdateModeSnapshot {
    param(
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    $values = @{}
    foreach ($policy in (Get-WinToolManagedUpdatePolicy -Catalog $Catalog)) {
        $item = Get-ItemProperty -LiteralPath $policy.path -Name $policy.name -ErrorAction SilentlyContinue
        if ($null -ne $item) {
            $values[(Get-WinToolUpdatePolicyKey -Policy $policy)] = [int]$item.($policy.name)
        }
    }
    $services = @{}
    foreach ($name in @("wuauserv", "UsoSvc")) {
        $service = Get-Service -Name $name -ErrorAction SilentlyContinue
        if ($null -ne $service) {
            $services[$name] = [string]$service.StartType
        }
    }
    return [pscustomobject]@{ Values = $values; Services = $services }
}

function Resolve-WinToolUpdateMode {
    param(
        [hashtable]$Values = @{},
        [hashtable]$Services = @{},
        $Catalog = (Get-WinToolUpdateCatalog)
    )
    # The current mode is the one whose policies are all in place and whose
    # disabled services really are disabled. Leftover values from another
    # tool show as "custom" so nothing gets mislabeled as Default.
    foreach ($mode in (Get-WinToolUpdateMode -Catalog $Catalog)) {
        $policies = @(Get-WinToolNote -Object $mode -Name "policies" -Default @())
        if ($policies.Count -eq 0) {
            continue
        }
        $match = $true
        foreach ($policy in $policies) {
            $key = Get-WinToolUpdatePolicyKey -Policy $policy
            if (-not $Values.ContainsKey($key) -or [int]$Values[$key] -ne [int]$policy.value) {
                $match = $false
            }
        }
        if ($match -and $Values.Count -eq $policies.Count) {
            return [string]$mode.id
        }
    }
    foreach ($name in @($Services.Keys)) {
        if ([string]$Services[$name] -eq "Disabled") {
            return "custom"
        }
    }
    if ($Values.Count -gt 0) {
        return "custom"
    }
    return "default"
}

function Test-WinToolUpdateModeCatalog {
    param(
        [Parameter(Mandatory = $true)]$Catalog,
        $Errors
    )
    $modes = @(Get-WinToolUpdateMode -Catalog $Catalog)
    $ids = @{}
    foreach ($mode in $modes) {
        $id = [string](Get-WinToolNote -Object $mode -Name "id" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or $ids.ContainsKey($id)) {
            $Errors.Add("An update mode has a missing or repeated id '$id'.")
            continue
        }
        $ids[$id] = $true
        foreach ($field in @("name", "description")) {
            if ([string]::IsNullOrWhiteSpace([string](Get-WinToolNote -Object $mode -Name $field -Default ""))) {
                $Errors.Add("Update mode '$id' needs a $field.")
            }
        }
        foreach ($policy in @(Get-WinToolNote -Object $mode -Name "policies" -Default @())) {
            if (-not ([string]$policy.path).StartsWith($script:WinToolUpdatePolicyRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
                $Errors.Add("Update mode '$id' writes outside the Windows Update policy key.")
            }
            if ([string]$policy.name -notmatch '^[A-Za-z]+$') {
                $Errors.Add("Update mode '$id' has an invalid policy name '$([string]$policy.name)'.")
            }
        }
        foreach ($service in @(Get-WinToolNote -Object $mode -Name "services" -Default @())) {
            if ($script:WinToolServiceStartTypes -notcontains [string]$service.startupType) {
                $Errors.Add("Update mode '$id' has an unknown startup type for $([string]$service.name).")
            }
            if ([string]$service.name -notmatch '^[A-Za-z]+$') {
                $Errors.Add("Update mode '$id' has an invalid service name.")
            }
        }
    }
    $default = Find-WinToolUpdateMode -Id "default" -Catalog $Catalog
    if ($null -eq $default) {
        $Errors.Add("updates.json needs a 'default' mode to revert to.")
    }
    elseif (@(Get-WinToolNote -Object $default -Name "policies" -Default @()).Count -ne 0) {
        $Errors.Add("The default update mode must not set policies.")
    }
}
# endregion

# region src/Private/System.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# DNS servers per network adapter and the Ultimate Performance power plan,
# both from data/system.json. Changes run as Windows PowerShell scripts through
# the plan runner so they are logged and never block the window.

function Get-WinToolSystemCatalog {
    return (Get-WinToolCachedPayloadObject -Name "System")
}

function Get-WinToolDnsProvider {
    param(
        $Catalog = (Get-WinToolSystemCatalog)
    )
    return @(Get-WinToolNote -Object $Catalog -Name "dns" -Default @())
}

function Find-WinToolDnsProvider {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Catalog = (Get-WinToolSystemCatalog)
    )
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $Catalog)) {
        if ([string]$provider.id -eq $Id) {
            return $provider
        }
    }
    return $null
}

function Get-WinToolDnsServerList {
    param(
        [Parameter(Mandatory = $true)]$Provider,
        [bool]$IncludeIpv6 = $true
    )
    $list = New-Object System.Collections.Generic.List[string]
    foreach ($address in @(Get-WinToolNote -Object $Provider -Name "ipv4" -Default @())) {
        $list.Add([string]$address)
    }
    if ($IncludeIpv6) {
        foreach ($address in @(Get-WinToolNote -Object $Provider -Name "ipv6" -Default @())) {
            $list.Add([string]$address)
        }
    }
    return $list.ToArray()
}

function Resolve-WinToolDnsProvider {
    param(
        [string[]]$Server = @(),
        $Catalog = (Get-WinToolSystemCatalog)
    )
    # Name the provider when every IPv4 server an adapter uses belongs to it.
    $ipv4 = @($Server | Where-Object { [string]$_ -match '^\d+\.\d+\.\d+\.\d+$' })
    if ($ipv4.Count -eq 0) {
        return $null
    }
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $Catalog)) {
        $known = @(Get-WinToolNote -Object $provider -Name "ipv4" -Default @())
        if ($known.Count -eq 0) {
            continue
        }
        $all = $true
        foreach ($address in $ipv4) {
            if ($known -notcontains [string]$address) {
                $all = $false
            }
        }
        if ($all) {
            return $provider
        }
    }
    return $null
}

function Get-WinToolDnsAdapter {
    if (-not (Test-WinToolWindows)) {
        return @()
    }
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($adapter in @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { [string]$_.Status -eq "Up" } | Sort-Object -Property Name)) {
        $servers = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @(Get-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -ErrorAction SilentlyContinue)) {
            foreach ($address in @($entry.ServerAddresses)) {
                $servers.Add([string]$address)
            }
        }
        $list.Add([pscustomobject]@{
            Index = [int]$adapter.ifIndex
            Name = [string]$adapter.Name
            Description = [string]$adapter.InterfaceDescription
            Servers = $servers.ToArray()
        })
    }
    return $list.ToArray()
}

function Format-WinToolDnsSummary {
    param(
        [Parameter(Mandatory = $true)]$Adapter,
        $Catalog = (Get-WinToolSystemCatalog)
    )
    $servers = @($Adapter.Servers)
    if ($servers.Count -eq 0) {
        return ("{0}: no DNS servers reported" -f [string]$Adapter.Name)
    }
    $text = "{0}: {1}" -f [string]$Adapter.Name, ($servers -join ", ")
    $provider = Resolve-WinToolDnsProvider -Server $servers -Catalog $Catalog
    if ($null -ne $provider) {
        $text += "  (" + [string]$provider.name + ")"
    }
    return $text
}

function ConvertTo-WinToolSingleQuoted {
    param(
        [AllowEmptyString()][string]$Text
    )
    return "'" + $Text.Replace("'", "''") + "'"
}

function Get-WinToolDnsScript {
    param(
        [Parameter(Mandatory = $true)][int[]]$InterfaceIndex,
        [Parameter(Mandatory = $true)]$Provider,
        [bool]$IncludeIpv6 = $true
    )
    $servers = @(Get-WinToolDnsServerList -Provider $Provider -IncludeIpv6 $IncludeIpv6)
    foreach ($address in $servers) {
        $parsed = $null
        if (-not [System.Net.IPAddress]::TryParse([string]$address, [ref]$parsed)) {
            throw (Get-WinToolText "msg.dns-provider-n-has-an-invalid-address-n" $([string]$Provider.id) $address)
        }
    }
    $indexText = (@($InterfaceIndex | ForEach-Object { [string][int]$_ })) -join ", "
    $serverText = (@($servers | ForEach-Object { ConvertTo-WinToolSingleQuoted -Text ([string]$_) })) -join ", "
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('$ErrorActionPreference = "Stop"')
    $lines.Add('$failed = 0')
    $lines.Add('$servers = @(' + $serverText + ')')
    $lines.Add('foreach ($index in @(' + $indexText + ')) {')
    $lines.Add('    $name = [string](Get-NetAdapter -InterfaceIndex $index).Name')
    $lines.Add('    try {')
    $lines.Add('        if ($servers.Count -eq 0) {')
    $lines.Add('            Set-DnsClientServerAddress -InterfaceIndex $index -ResetServerAddresses')
    $lines.Add('            Write-Output ($name + ": DNS is automatic again")')
    $lines.Add('        }')
    $lines.Add('        else {')
    $lines.Add('            Set-DnsClientServerAddress -InterfaceIndex $index -ServerAddresses $servers')
    $lines.Add('            Write-Output ($name + ": DNS set to " + ($servers -join ", "))')
    $lines.Add('        }')
    $lines.Add('    }')
    $lines.Add('    catch {')
    $lines.Add('        $failed++')
    $lines.Add('        Write-Output ($name + ": " + $_.Exception.Message)')
    $lines.Add('    }')
    $lines.Add('}')
    $lines.Add('Clear-DnsClientCache')
    $lines.Add('if ($failed -gt 0) { exit 2 }')
    return ($lines -join [Environment]::NewLine)
}

function Get-WinToolDnsPlan {
    param(
        [Parameter(Mandatory = $true)]$Adapter,
        [Parameter(Mandatory = $true)]$Provider,
        [bool]$IncludeIpv6 = $true
    )
    $adapters = @($Adapter)
    if ($adapters.Count -eq 0) {
        throw (Get-WinToolText "msg.pick-a-network-adapter-first")
    }
    $names = (@($adapters | ForEach-Object { [string]$_.Name })) -join ", "
    return @([pscustomobject]@{
        Type = "inline-script"
        Label = ("Set DNS to {0} on {1}" -f [string]$Provider.name, $names)
        Name = "dns"
        Text = (Get-WinToolDnsScript -InterfaceIndex @($adapters | ForEach-Object { [int]$_.Index }) -Provider $Provider -IncludeIpv6 $IncludeIpv6)
    })
}

function Get-WinToolSystemProbeScript {
    # Runs off the UI thread. Returns adapter rows and powercfg text as strings.
    $scriptText = @'
param($Sync)
$ErrorActionPreference = "Continue"
try {
    $records = New-Object System.Collections.Generic.List[string]
    $unit = [string][char]31
    $record = [string][char]30
    $adapters = @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { [string]$_.Status -eq "Up" } | Sort-Object -Property Name)
    foreach ($adapter in $adapters) {
        $servers = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @(Get-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -ErrorAction SilentlyContinue)) {
            foreach ($address in @($entry.ServerAddresses)) {
                $text = [string]$address
                if (-not [string]::IsNullOrWhiteSpace($text)) { $servers.Add($text) }
            }
        }
        $name = ([string]$adapter.Name).Replace($unit, " ").Replace($record, " ").Replace("`r", " ").Replace("`n", " ")
        $description = ([string]$adapter.InterfaceDescription).Replace($unit, " ").Replace($record, " ").Replace("`r", " ").Replace("`n", " ")
        $records.Add(([string][int]$adapter.ifIndex) + $unit + $name + $unit + $description + $unit + (($servers.ToArray()) -join ","))
    }
    $Sync.Adapters = ($records.ToArray() -join $record)
    try {
        $Sync.Power = [string]((& powercfg.exe /list) | Out-String)
        $Sync.PowerError = ""
    }
    catch {
        $Sync.Power = ""
        $Sync.PowerError = $_.Exception.Message
    }
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
finally {
    $Sync.Done = $true
}
'@
    return $scriptText
}

function ConvertFrom-WinToolSystemProbe {
    param([AllowEmptyString()][string]$Text)
    $list = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrWhiteSpace($Text)) {
        return @()
    }
    $record = [string][char]30
    foreach ($line in @($Text -split [regex]::Escape($record))) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        $part = @($line.Split([char]31))
        $index = 0
        [void][int]::TryParse([string]$part[0], [ref]$index)
        $name = ""
        $description = ""
        $servers = @()
        if ($part.Length -ge 2) { $name = [string]$part[1] }
        if ($part.Length -ge 3) { $description = [string]$part[2] }
        if ($part.Length -ge 4 -and -not [string]::IsNullOrWhiteSpace([string]$part[3])) {
            $servers = @([string]$part[3] -split ",")
        }
        $list.Add([pscustomobject]@{
            Index = $index
            Name = $name
            Description = $description
            Servers = $servers
        })
    }
    return $list.ToArray()
}

function ConvertFrom-WinToolPowerList {
    param(
        [string]$Text
    )
    # powercfg /list is translated, so read only the GUID, the name in
    # parentheses, and the trailing * that marks the active plan.
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($line in @($Text -split "`r?`n")) {
        $match = [regex]::Match($line, '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s*\((.*)\)\s*(\*?)\s*$')
        if ($match.Success) {
            $list.Add([pscustomobject]@{
                Guid = $match.Groups[1].Value.ToLowerInvariant()
                Name = $match.Groups[2].Value
                Active = ($match.Groups[3].Value -eq "*")
            })
        }
    }
    return $list.ToArray()
}

function Get-WinToolPowerPlanState {
    param(
        $Scheme = @(),
        $Catalog = (Get-WinToolSystemCatalog)
    )
    $plan = Get-WinToolNote -Object $Catalog -Name "powerPlan"
    $copy = ([string]$plan.copyGuid).ToLowerInvariant()
    $base = ([string]$plan.baseGuid).ToLowerInvariant()
    $state = [pscustomobject]@{ Added = $false; BuiltIn = $false; Active = $false }
    foreach ($item in @($Scheme)) {
        if ([string]$item.Guid -eq $copy) {
            $state.Added = $true
            if ($item.Active) { $state.Active = $true }
        }
        if ([string]$item.Guid -eq $base) {
            $state.BuiltIn = $true
            if ($item.Active) { $state.Active = $true }
        }
    }
    return $state
}

function Format-WinToolPowerPlanStatus {
    param(
        [Parameter(Mandatory = $true)]$State,
        [string]$Name = (Get-WinToolText "catalog.system.powerPlan.name")
    )
    if ($State.Added) {
        if ($State.Active) { return "$Name is added and active." }
        return "$Name is added but another plan is active."
    }
    if ($State.BuiltIn) {
        if ($State.Active) { return "$Name is built into this Windows and active." }
        return "$Name is built into this Windows. Adding it switches to it."
    }
    return "$Name is not on this PC."
}

function Get-WinToolPowerPlanScript {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("add", "remove")][string]$Action,
        $Catalog = (Get-WinToolSystemCatalog)
    )
    $plan = Get-WinToolNote -Object $Catalog -Name "powerPlan"
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('$base = ' + (ConvertTo-WinToolSingleQuoted -Text ([string]$plan.baseGuid)))
    $lines.Add('$copy = ' + (ConvertTo-WinToolSingleQuoted -Text ([string]$plan.copyGuid)))
    $lines.Add('$fallback = ' + (ConvertTo-WinToolSingleQuoted -Text ([string]$plan.fallbackGuid)))
    $lines.Add('$list = (& powercfg.exe /list | Out-String)')
    if ($Action -eq "add") {
        $lines.Add('if ($list -match $copy) {')
        $lines.Add('    $target = $copy')
        $lines.Add('}')
        $lines.Add('elseif ($list -match $base) {')
        $lines.Add('    $target = $base')
        $lines.Add('}')
        $lines.Add('else {')
        $lines.Add('    & powercfg.exe -duplicatescheme $base $copy')
        $lines.Add('    if ($LASTEXITCODE -ne 0) {')
        $lines.Add('        Write-Output "Windows did not allow the Ultimate Performance plan on this PC. Some laptops with Modern Standby block it."')
        $lines.Add('        exit 2')
        $lines.Add('    }')
        $lines.Add('    $target = $copy')
        $lines.Add('    Write-Output "Added the Ultimate Performance plan."')
        $lines.Add('}')
        $lines.Add('& powercfg.exe -setactive $target')
        $lines.Add('if ($LASTEXITCODE -ne 0) { exit 2 }')
        $lines.Add('Write-Output "Ultimate Performance is now the active plan."')
    }
    else {
        $lines.Add('if ($list -notmatch $copy) {')
        $lines.Add('    Write-Output "WinTool did not add an Ultimate Performance plan, so there is nothing to remove."')
        $lines.Add('    if ($list -match $base) { Write-Output "The built-in copy stays. Pick another plan in Control Panel if you want to stop using it." }')
        $lines.Add('    exit 0')
        $lines.Add('}')
        $lines.Add('$active = (& powercfg.exe /getactivescheme | Out-String)')
        $lines.Add('if ($active -match $copy) {')
        $lines.Add('    & powercfg.exe -setactive $fallback')
        $lines.Add('    Write-Output "Switched back to the Balanced plan."')
        $lines.Add('}')
        $lines.Add('& powercfg.exe -delete $copy')
        $lines.Add('if ($LASTEXITCODE -ne 0) { exit 2 }')
        $lines.Add('Write-Output "Removed the Ultimate Performance plan."')
    }
    return ($lines -join [Environment]::NewLine)
}

function Get-WinToolPowerPlanPlan {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("add", "remove")][string]$Action,
        $Catalog = (Get-WinToolSystemCatalog)
    )
    $label = "Add the Ultimate Performance power plan"
    if ($Action -eq "remove") {
        $label = "Remove the Ultimate Performance power plan"
    }
    return @([pscustomobject]@{
        Type = "inline-script"
        Label = $label
        Name = "power-plan"
        Text = (Get-WinToolPowerPlanScript -Action $Action -Catalog $Catalog)
    })
}

function Test-WinToolSystemCatalog {
    param(
        [Parameter(Mandatory = $true)]$Catalog,
        $Errors
    )
    if ([int](Get-WinToolNote -Object $Catalog -Name "schemaVersion" -Default 0) -ne 1) {
        $Errors.Add("system.json schemaVersion must be 1.")
    }
    $ids = @{}
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $Catalog)) {
        $id = [string](Get-WinToolNote -Object $provider -Name "id" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or $ids.ContainsKey($id)) {
            $Errors.Add("A DNS provider has a missing or repeated id '$id'.")
            continue
        }
        $ids[$id] = $true
        foreach ($family in @("ipv4", "ipv6")) {
            $expected = [System.Net.Sockets.AddressFamily]::InterNetwork
            if ($family -eq "ipv6") {
                $expected = [System.Net.Sockets.AddressFamily]::InterNetworkV6
            }
            foreach ($address in @(Get-WinToolNote -Object $provider -Name $family -Default @())) {
                $parsed = $null
                if (-not [System.Net.IPAddress]::TryParse([string]$address, [ref]$parsed) -or $parsed.AddressFamily -ne $expected) {
                    $Errors.Add("DNS provider '$id' has an invalid $family address '$address'.")
                }
            }
        }
    }
    if (-not $ids.ContainsKey("dhcp")) {
        $Errors.Add("system.json needs a 'dhcp' DNS choice to go back to automatic.")
    }
    $plan = Get-WinToolNote -Object $Catalog -Name "powerPlan"
    foreach ($field in @("baseGuid", "copyGuid", "fallbackGuid")) {
        $value = [string](Get-WinToolNote -Object $plan -Name $field -Default "")
        if ($value -notmatch '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') {
            $Errors.Add("powerPlan.$field must be a lowercase GUID.")
        }
    }
}
